import "core-js/modules/es.array.concat.js";
import { defineComponent, inject, h } from '@vue/composition-api';
import { PageModuleType } from '@/main/utils/types';
import styles from './index.module.scss';
import Images from '@/main/components/images';
import { XiaoxueMathJumpCode } from '@/config/templateCode';
import { pageNoInjectKey } from '@/config/types';

/** 小学数学同步学习 封底组件 */
export default defineComponent({
  name: 'MathTBXXBackCover',
  props: {
    data: {
      type: Object,
      require: true
    },
    /** 用于指学框的唯一标识 */
    code: {
      type: String
    },
    /** 是否显示二维码图片 */
    isShow: {
      type: Boolean,
      default: false
    }
  },
  setup: function setup() {
    var pageNoRoot = inject(pageNoInjectKey, {});
    return function () {
      return h("div", {
        "class": styles.backCover,
        "attrs": {
          "code": "".concat(XiaoxueMathJumpCode.back_cover.code, "-").concat(pageNoRoot.pageNo, "-").concat(pageNoRoot.continuePageNo),
          "pageType": PageModuleType.backCover
        }
      }, [h("div", {
        "class": styles.bgImage
      }, [h(Images, {
        "attrs": {
          "img": {
            src: require('@/assets/image/MathTBXXBackCover.jpg'),
            width: '100%',
            height: '100%'
          },
          "styles": {
            maxHeight: '100%'
          }
        }
      })])]);
    };
  }
});