import "core-js/modules/es.regexp.exec.js";
import "core-js/modules/es.string.replace.js";
import { defineComponent, watch, ref, h } from '@vue/composition-api';
import Images from '@/main/components/images';
import styles from './index.module.scss';
import VueQr from 'vue-qr';

/** 二维码组件 */
export default defineComponent({
  name: 'QrCode',
  props: {
    /** 二维码url */
    src: {
      type: String,
      default: ''
    },
    /** 是否显示二维码图片 */
    isShow: {
      type: Boolean,
      default: false
    },
    width: {
      type: String,
      default: '90px'
    },
    height: {
      type: String,
      default: '70px'
    },
    /** 是否自动生成二维码 */
    isGenerateAuto: {
      type: Boolean,
      default: false
    }
  },
  setup: function setup(props) {
    var qrCodeSrc = ref('');
    watch(function () {
      return props.src;
    }, function (val) {
      qrCodeSrc.value = val;
    }, {
      immediate: true,
      deep: true
    });
    return function () {
      return props.isShow && qrCodeSrc.value && (props.isGenerateAuto ? h(VueQr, {
        "attrs": {
          "size": parseInt(props.width.replace('px', '')),
          "text": qrCodeSrc.value,
          "white-margin": false,
          "margin": 0
        }
      }) : h("div", {
        "class": styles.qrCode,
        "style": {
          width: props.width,
          height: props.height
        }
      }, [h(Images, {
        "attrs": {
          "img": {
            src: qrCodeSrc.value
          }
        }
      })]));
    };
  }
});