import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.object.to-string.js";
import "core-js/modules/web.dom-collections.for-each.js";
import { TemplateServiceCode, TemplateWebCode } from '@/config/templateCode';
/**
 * @description 数据解析模块，构造组装pdf中渲染的最小模块数据curItem
 * @param treeData 当前课文结构
 */
export default function dataAnalysis(treeData) {
  var curItem = {
    id: 1,
    name: 1,
    isMockPage: true,
    children: []
  };
  treeData.forEach(function (item) {
    item.children.forEach(function (itemChild) {
      // 是否模块有单元拓展
      itemChild.answerData.forEach(function (answerDataItem, answerDataItemIdx) {
        if (answerDataItem.answerList.length) {
          curItem.children.push({
            type: TemplateServiceCode.title_general,
            data: {
              mclItem: {
                moduleName: answerDataItem.moduleName
              }
            },
            customStyle: {
              padding: '8px 0 4px 23px'
            }
          });
        } else {
          curItem.children.push({
            type: TemplateWebCode.article_onetitle,
            data: {
              name: answerDataItem.moduleName,
              titleMaxWidth: 308
            }
          });
        }
        answerDataItem.answerList.forEach(function (answerContentItem, answerContentItemIdx) {
          var isLastAnswerContentItem = answerContentItemIdx === answerDataItem.answerList.length - 1;
          var answerContentCustomStyle = {
            // 自定义答案内容样式
            paddingBottom: '0'
          };
          if (isLastAnswerContentItem && itemChild.answerData[answerDataItemIdx + 1]) {
            answerContentCustomStyle.paddingBottom = itemChild.answerData[answerDataItemIdx + 1].answerList.length ? '8px' : '32px';
          }
          if (answerContentItem.children.length) {
            // 处理套题答案
            answerContentItem.children.forEach(function (answerChild, answerChildIdx) {
              curItem.children.push({
                type: TemplateWebCode.answer_content,
                data: {
                  text: answerChild.answer,
                  curNo: answerChildIdx === 0 ? answerContentItemIdx + 1 : 0,
                  isChild: true,
                  childCurNo: answerChildIdx + 1
                },
                customStyle: answerContentCustomStyle
              });
            });
          } else {
            curItem.children.push({
              type: TemplateWebCode.answer_content,
              data: {
                text: answerContentItem.answer,
                curNo: answerContentItemIdx + 1
              },
              customStyle: answerContentCustomStyle
            });
          }
        });
      });
    });
  });
  return curItem;
}