import "core-js/modules/es.number.constructor.js";
import { defineComponent, h } from '@vue/composition-api';
import Word from '@/main/components/word';
import { MenuLevelTransferPro } from '@/main/utils/types';
import styles from './index.module.scss';
import { navToPage } from '@/main/utils';

/** 目录页的文章标题组件 */
export default defineComponent({
  name: 'MenuTitle',
  props: {
    /** 文章标题 */
    title: {
      type: String,
      default: ''
    },
    /** 文章对应页码 */
    pageNo: {
      type: Number,
      default: 1
    }
  },
  setup: function setup(props) {
    var titleFont = {
      fontSize: 15,
      color: '#3F9AD5',
      lineHeight: 24
    };
    var pageFont = {
      color: '#3F9AD5',
      fontSize: 14
    };
    return function () {
      return h("div", {
        "class": styles.articleUnit,
        "style": {
          height: MenuLevelTransferPro.getLabel('MathTBXXLevelTwo') + 'px'
        },
        "on": {
          "click": function click() {
            return navToPage(props.pageNo);
          }
        }
      }, [h(Word, {
        "style": {
          margin: '0px'
        },
        "attrs": {
          "font": titleFont,
          "content": props.title
        }
      }), h("div", {
        "class": styles.dot
      }), h(Word, {
        "attrs": {
          "font": pageFont,
          "content": String(props.pageNo)
        }
      })]);
    };
  }
});