export default function (emit) {
  // 功能列表
  var compFunctionList = [{
    value: 0,
    label: '修改',
    icon: 'el-icon-edit'
  },
  // {
  //   value: 1,
  //   label: '新增'
  // },
  {
    value: 2,
    label: '删除',
    icon: 'el-icon-close'
  }];
  var methods = {
    /**
     * 组件功能选择
     */
    functionTap: function functionTap(e, value) {
      if (e.stopPropagation) {
        e.stopPropagation();
      }
      emit('function-choose', value);
    }
  };
  return {
    compFunctionList: compFunctionList,
    methods: methods
  };
}