import "core-js/modules/es.array.includes.js";
import "core-js/modules/es.number.constructor.js";
import "core-js/modules/es.regexp.exec.js";
import "core-js/modules/es.string.includes.js";
import "core-js/modules/es.string.match.js";
import { MenuLevelTransferPro } from '@/main/utils/types';
import { reactive } from '@vue/composition-api';
export default function (props) {
  var imgInfo = reactive({
    src: '',
    width: 18,
    verticalAlign: 'middle'
  });
  // 语文园地前面放置ChineseTBXXMenuMaozi
  if (props.title.includes('语文园地')) {
    imgInfo.src = require('@/assets/image/ChineseTBXXMenuMaozi.png');
    // 同步阅读和作文前面都放置ChineseTBXXMenuStar
  } else if (props.title.includes(':')) {
    imgInfo.src = require('@/assets/image/ChineseTBXXMenuStar.png');
  }
  // 当前标题类型
  var titleType = reactive({
    mainText: false,
    ywyd: false,
    tbyd: false,
    tbzw: false
  });
  // 如果没有语文园地|:，则是正文(包含有序号和无序号), 同步阅读和同步作文都有:
  if (!props.title.match(/语文园地|:/)) {
    titleType.mainText = true;
    // 语文园地
  } else if (props.title.match(/语文园地/)) {
    titleType.ywyd = true;
    // 同步阅读
  } else if (props.title.match(/阅读/)) {
    titleType.tbyd = true;
    // 同步作文
  } else {
    titleType.tbzw = true;
  }
  var font = {
    fontSize: 15,
    fontFamily: 'siyuanheiti-medium',
    color: titleType.mainText ? '#434143' : '#b96a45',
    lineHeight: Number(MenuLevelTransferPro.getLabel('levelTwo')),
    whiteSpace: 'nowrap'
  };
  return {
    font: font,
    titleType: titleType,
    imgInfo: imgInfo
  };
}