// 插入节点
var insertHtml = function insertHtml(html) {
  var selection = window.getSelection();
  if (selection.getRangeAt && selection.rangeCount) {
    var range = selection.getRangeAt(0);
    range.deleteContents();
    // let $theEditDiv = range.commonAncestorContainer && range.commonAncestorContainer.__vue__;
    var $theEditDiv = range.commonAncestorContainer;
    // Range.createContextualFragment() would be useful here but is
    // non-standard and not supported in all browsers (IE9, for one)
    var el = document.createElement('div');
    el.innerHTML = html;
    var frag = document.createDocumentFragment();
    var node;
    var lastNode;
    while (node = el.firstChild) {
      lastNode = frag.appendChild(node);
    }
    range.insertNode(frag);
    // range.setEndAfter(c);
    // Preserve the selection
    if (lastNode) {
      range = range.cloneRange();
      if (html.indexOf('<br') === 0) {
        range.setStartAfter(lastNode);
        range.collapse(true);

        // document.execCommand('insertHTML', false, html);
        // return;
      } else if (includesInArr(html, ['<img ', ' <audio ', '<pos ', ' <data ', ' <span class="pinyin', ' <sequence', '<order', ' <video-relation'])) {
        document.execCommand('insertHTML', false, html);
        return;
      } else {
        range.selectNodeContents(lastNode);
        range.collapse(false);
      }
      selection.removeAllRanges();
      selection.addRange(range);
      if (html.indexOf(' <pos ') === 0 || html.indexOf(' <data ') === 0 || html.indexOf(' <span class="pinyin') === 0 || html.indexOf('<edit-error') === 0) {
        range.setStartAfter(lastNode);
        setTimeout(function () {
          range.setStartAfter(lastNode);
        });
      }
      // 光标位置后移一个
      // if (html.indexOf(' <pos ') === 0) {
      //     document.execCommand('insertHTML', false, '');
      //     return;
      // }
    }
    // 插入空字符串监听变化
    document.execCommand('insertHTML', false, '');
    if ($theEditDiv) {
      // $theEditDiv.changeText();
      // 模拟触发input事件，更改editDiv的value
      var evt = document.createEvent('HTMLEvents');
      evt.initEvent('input', true, true);
      $theEditDiv.dispatchEvent(evt);
    }
    // 新版火狐插入元素无效, 需要特殊处理, 插入空格再删除
    if (navigator.userAgent.indexOf('Firefox') > 0) {
      document.execCommand('insertHTML', false, ' ');
      document.execCommand('delete', false, null);
    }
  }
};
// 字符串是否包含数组中的某一项
var includesInArr = function includesInArr(str, arr) {
  var result = false;
  for (var i = 0; i < arr.length; i++) {
    if (str.startsWith(arr[i])) {
      result = true;
      break;
    }
  }
  return result;
};
// 插入之前的格式化
var editorInsert = function editorInsert(html) {
  if (html === '') {
    return;
  }
  insertHtml(html);
};
export default editorInsert;