import "core-js/modules/es.number.constructor.js";
import { defineComponent, h } from '@vue/composition-api';
import Word from '@/main/components/word';
import { navToPage } from '@/main/utils';
import styles from './index.module.scss';
import { MenuLevelTransferPro } from '@/main/utils/types';

/** 目录页的一级标题组件 */
export default defineComponent({
  name: 'MenuOneTitle',
  props: {
    /** 文章目录标题 */
    title: {
      type: String,
      default: ''
    },
    /** 文章对应页码 */
    pageNo: {
      type: Number,
      default: 1
    }
  },
  setup: function setup(props) {
    return function () {
      return h("div", {
        "class": styles.articleMenu,
        "style": {
          height: MenuLevelTransferPro.getLabel('levelModule') + 'px'
        },
        "on": {
          "click": function click() {
            return navToPage(props.pageNo);
          }
        }
      }, [h(Word, {
        "attrs": {
          "font": {
            color: '#595656',
            fontSize: 16,
            fontFamily: 'siyuanheiti-medium'
          },
          "content": props.title
        }
      }), h("div", {
        "class": styles.dot
      }), h(Word, {
        "attrs": {
          "font": {
            color: '#B5B5B6',
            fontSize: 16
          },
          "content": String(props.pageNo)
        }
      })]);
    };
  }
});