import { defineComponent, h } from '@vue/composition-api';
import PageHeader from '@/main/components/page/header';
import { PageModuleType } from '@/main/utils/types';
import styles from './index.module.scss';
import Images from '@/main/components/images';

/** 小学数学同步学习宣传页组件 */
export default defineComponent({
  name: 'MathTBXXPublicity',
  props: {
    /** 是否渲染页眉(页眉本身是否存在) */
    hasPageHeader: {
      type: Boolean,
      default: false
    },
    /** 是否渲染页眉内部的数据(当hasPageHeader为true时生效) */
    renderPageHeader: {
      type: Boolean,
      default: false
    },
    data: {
      type: Object,
      require: true
    },
    /** 用于指学框的唯一标识 */
    code: {
      type: [String, Array]
    },
    /** 宣传页图片 */
    bgImage: {
      type: String
    }
  },
  setup: function setup(props) {
    return function () {
      return h("div", {
        "class": styles.publicityBox,
        "attrs": {
          "pageType": PageModuleType.publicity
        }
      }, [h(Images, {
        "attrs": {
          "img": {
            src: props.bgImage,
            width: '100%',
            height: '100%'
          },
          "styles": {
            maxHeight: '100%'
          }
        }
      }), props.hasPageHeader && h(PageHeader, {
        "class": styles.publicityHeader,
        "attrs": {
          "renderPageHeader": props.renderPageHeader,
          "type": props.data.type,
          "ocr": props.data.ocr,
          "qrCode": props.data.qrCode
        }
      })]);
    };
  }
});