import "core-js/modules/es.array.filter.js";
import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.object.to-string.js";
import "core-js/modules/web.dom-collections.for-each.js";
import { TemplateWebCode } from '@/config/templateCode';
/**
 * @description 数据解析模块，构造组装pdf中渲染的最小模块数据curItem
 * @param treeData 当前课文结构
 */
export default function dataAnalysis(treeData) {
  var curItem = {
    id: 1,
    name: 1,
    isMockPage: true,
    children: []
  };
  treeData.forEach(function (item, itemIdx) {
    curItem.children.push({
      type: TemplateWebCode.catalog_title,
      data: {
        name: item.label,
        font: {
          fontSize: '22px',
          lineHeight: '34px'
        }
      },
      customStyle: {
        paddingTop: itemIdx !== 0 && '30px'
      }
    });
    item.children.forEach(function (itemChild, itemChildIndex) {
      // 无答案不显示模块标题
      itemChild.answerData.length && curItem.children.push({
        type: TemplateWebCode.catalog_title,
        data: {
          name: itemChild.label,
          font: {
            fontSize: '20px',
            lineHeight: '30px'
          }
        },
        customStyle: {
          paddingTop: itemChildIndex !== 0 && '30px',
          paddingBottom: '30px'
        }
      });
      /** 设置解析 */
      function setExplanationContent(val) {
        var isChild = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : false;
        val.explanation && val.explanation.split('\n').filter(function (fItem) {
          return fItem;
        }).forEach(function (alysItem, alysIndex) {
          curItem.children.push({
            type: TemplateWebCode.answer_content,
            data: {
              labelContent: alysIndex === 0 ? '<strong>解析:</strong>' : '',
              text: alysItem,
              isHideChildCurNo: true,
              isChild: isChild
            }
          });
        });
      }
      itemChild.answerData.forEach(function (answerDataItem, answerDataItemIdx) {
        answerDataItem.answerList.forEach(function (answerContentItem, answerContentItemIdx) {
          if (answerContentItem.children.length) {
            // 处理套题答案
            answerContentItem.children.forEach(function (answerChild, answerChildIdx) {
              curItem.children.push({
                type: TemplateWebCode.answer_content,
                data: {
                  labelContent: '<strong>答案:</strong>',
                  text: answerChild.answer,
                  curNo: answerChildIdx === 0 ? answerContentItemIdx + 1 : 0,
                  isChild: true,
                  childCurNo: answerChildIdx + 1
                },
                customStyle: {
                  paddingTop: !(answerDataItemIdx === 0 && answerContentItemIdx === 0 && answerChildIdx === 0) && '20px'
                }
              });
              setExplanationContent(answerChild, true);
            });
          } else {
            curItem.children.push({
              type: TemplateWebCode.answer_content,
              data: {
                labelContent: '<strong>答案:</strong>',
                text: answerContentItem.answer,
                curNo: answerContentItemIdx + 1
              },
              customStyle: {
                paddingTop: !(answerDataItemIdx === 0 && answerContentItemIdx === 0) && '20px'
              }
            });
            setExplanationContent(answerContentItem);
          }
        });
      });
    });
  });
  return curItem;
}