export default {
  _initData: {
    /** 题目说明 */
    explainContent: {
      value: ' ',
      disabled: false,
      require: true
    },
    /** 题干 */
    titleContent: {
      value: ' ',
      disabled: false,
      require: true
    },
    /** 手绘区域 */
    questionAreaContent: {
      value: '',
      disabled: false,
      require: true
    }
  },
  setInitData: function setInitData(States, questionData, disabled) {
    States.formData.explainContent.value = questionData.questionExplain;
    States.formData.titleContent.value = questionData.prompt;
    States.formData.questionAreaContent.value = questionData.freeHandArea;
    States.formData.explainContent.disabled = disabled;
    States.formData.titleContent.disabled = disabled;
    States.formData.questionAreaContent.disabled = disabled;
  }
};