import { defineComponent, h } from '@vue/composition-api';
import Word from '@/main/components/word';
import styles from './index.module.scss';
import { MenuLevelTransferPro } from '@/main/utils/types';

/** 目录页的单元标题组件 */
export default defineComponent({
  name: 'MenuChapter',
  props: {
    /** 单元号 */
    chapterNo: {
      type: String,
      default: ''
    }
  },
  setup: function setup(props) {
    var font = {
      fontSize: 18,
      fontFamily: 'siyuanheiti-bold',
      color: '#745D50',
      lineHeight: 38,
      verticalAlign: 'super'
    };
    return function () {
      return h("div", {
        "class": styles.menuChapter,
        "style": {
          height: MenuLevelTransferPro.getLabel('levelOne') + 'px'
        }
      }, [h("img", {
        "attrs": {
          "src": require('@/assets/image/pageDecorate.png')
        }
      }), h("div", {
        "class": styles.menuChapterTitle
      }, [h(Word, {
        "attrs": {
          "font": font,
          "content": props.chapterNo
        }
      })])]);
    };
  }
});