import dataAnalysis from '../dataAnalysis/102/1/TBXXAnswer';
import dataAnalysis_24_1 from '../dataAnalysis/102/1/TBXXAnswer-24-1';
import TBYLDataAnalysis from '../dataAnalysis/102/1/TBYLAnswer';
import HJYXDataAnalysis from '../dataAnalysis/102/1/HJYXAnswer';
import dataAnalysisDZKYL_24_4 from '../dataAnalysis/102/1/DZKYLAnswer-24-4';
import dataAnalysisDZKYL_25_2 from '../dataAnalysis/102/1/DZKYLAnswer-25-2';
import dataAnalysisQZFXYL_25_3 from '../dataAnalysis/102/1/QZFXYLAnswer-25-3';
import { PeriodSubjectCategoryEnum } from '@/config/types';

/** 答案手册数据处理 */
export default function dataAnalysisAnswer(item, periodSubjectCategory) {
  switch (periodSubjectCategory.value // 当前手册类型
  ) {
    case PeriodSubjectCategoryEnum.XIAOXUE_MATH_TBXX:
      return dataAnalysis(item);
    case PeriodSubjectCategoryEnum.XIAOXUE_MATH_TBXX_24_1:
    case PeriodSubjectCategoryEnum.XIAOXUE_MATH_TBXX_24_3:
      return dataAnalysis_24_1(item);
    case PeriodSubjectCategoryEnum.XIAOXUE_MATH_DZKYL_25_2:
    case PeriodSubjectCategoryEnum.XIAOXUE_MATH_DZKYL_25_3:
    case PeriodSubjectCategoryEnum.CHUZHONG_MATH_DZKYL_26_2:
      return dataAnalysisDZKYL_25_2(item);
    case PeriodSubjectCategoryEnum.XIAOXUE_MATH_TBYL_24_1:
    case PeriodSubjectCategoryEnum.CHUZHONG_MATH_TBYL_24_1:
    case PeriodSubjectCategoryEnum.XIAOXUE_CHINESE_TBYL_24_3:
      return TBYLDataAnalysis(item);
    case PeriodSubjectCategoryEnum.XIAOXUE_MATH_HJYX:
    case PeriodSubjectCategoryEnum.XIAOXUE_MATH_SJYX_25_2:
      return HJYXDataAnalysis(item);
    case PeriodSubjectCategoryEnum.XIAOXUE_MATH_DZKYL:
      return dataAnalysisDZKYL_24_4(item);
    case PeriodSubjectCategoryEnum.XIAOXUE_MATH_QZFXYL_25_3:
      return dataAnalysisQZFXYL_25_3(item);
  }
}